      license: "GPL-3.0",
      topics: [],
      desc_zh: "QuickWork / Amazon Quick → OpenAI API  把 Amazon Quick（QuickWork）桌面端的聊天能力转换成**OpenAI 兼容的 HTTP API**。  项目是单一 Go 可执行文件：原生 OAuth 登录、账号存储、token 刷新和反代全部由 Go 完成，不需要 Python，也不用启动官方桌面应用或 outpost 进程。登录后，反向代理会将 `/v1/chat/completions` 请求转换为 QuickWork WebSocket 帧，并将结果转换回普通 JSON 或 SSE。"
